package com.acme.preview.mapper;

import com.acme.preview.event.PriceEvent;

import java.util.function.Function;

/**
 * Maps a CSV line ("symbol,price,volume") to a {@link PriceEvent}. Wired as the file feed's
 * valueMapper, so the hosted graph receives typed PriceEvents rather than raw Strings.
 * Implements {@code Function<Object,?>} (the feed-wrapper's value type) and tolerates blank or
 * short lines (e.g. a trailing newline) so the feed never throws.
 */
public class CsvToPriceEvent implements Function<Object, PriceEvent> {

    @Override
    public PriceEvent apply(Object event) {
        String line = String.valueOf(event);
        String[] f = line.split(",");
        if (f.length < 3) {
            return new PriceEvent(line.trim(), 0.0, 0L);
        }
        return new PriceEvent(f[0].trim(), Double.parseDouble(f[1].trim()), Long.parseLong(f[2].trim()));
    }
}
package com.acme.preview.node;

import com.acme.preview.event.*;
import com.telamin.fluxtion.runtime.annotations.OnEventHandler;
import com.telamin.fluxtion.runtime.audit.EventLogNode;

/**
 * The event-handler node — generated by the Fluxtion project starter.
 * One {@code @OnEventHandler} per declared event type.
 * Extends EventLogNode so each handler can audit via {@code auditLog}.
 * Stores the latest event; RiskCheck reacts downstream via {@code @OnTrigger}.
 */
public class RootNode extends EventLogNode {

    /** Most recent event handled; read by RiskCheck on trigger. */
    private Object latestEvent;

    public Object getLatestEvent() {
        return latestEvent;
    }

    // Implement this event callback according to the XML declaration and callback return contract. See https://fluxtion-playground.dev/spring-authoring/contract.md#local-authoring-workflow-and-extended-declarations
    @OnEventHandler
    public boolean onPriceEvent(PriceEvent event) {
        auditLog.info("receivedEvent", event);
        auditLog.info("price", event.price());
        auditLog.info("volume", event.volume());
        this.latestEvent = event;
        // TODO: handle PriceEvent
        return true;
    }
}
package com.acme.preview.node;

import com.telamin.fluxtion.runtime.annotations.OnTrigger;

/**
 * Trigger node — generated by the Fluxtion project starter. References RootNode; callback behaviour follows the XML declarations and Java annotations.
 */
public class RiskCheck {

    // This reference's propagation mode is declared in the XML; it does not make the referenced object immutable. See https://fluxtion-playground.dev/spring-authoring/contract.md#local-authoring-workflow-and-extended-declarations
    private final RootNode rootNode;
    private Object latestEvent;

    public RiskCheck(RootNode rootNode) {
        this.rootNode = rootNode;
    }

    /** Most recent event seen; read by downstream nodes on trigger. */
    public Object getLatestEvent() {
        return latestEvent;
    }

    // Implement this trigger callback according to the XML declaration and callback return contract. See https://fluxtion-playground.dev/spring-authoring/contract.md#local-authoring-workflow-and-extended-declarations
    @OnTrigger
    public boolean onRiskCheck() {
        Object event = rootNode.getLatestEvent();
        this.latestEvent = event;
        // TODO: react to the updated RootNode state
        return true;
    }
}
